class SearchIndex {
  constructor() {
    this.index = new Map(); // item_name -> {tier, category, subcategory}
    this.lastUpdate = null;
    this.updateInterval = 60 * 60 * 1000; // 1 hour in milliseconds
  }

  async updateIndex() {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_BASE_URL}/items/search-index`);
      
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }
      
      const data = await response.json();
      
      // Check if the response contains an error
      if (data.detail) {
        throw new Error(`API Error: ${data.detail}`);
      }
      
      // Clear existing index
      this.index.clear();
      
      // Handle different possible response structures
      let items = [];
      if (data && data.items) {
        items = data.items;
      } else if (Array.isArray(data)) {
        items = data;
      } else if (data && data.results) {
        items = data.results;
      } else {
        console.warn('Unexpected API response structure:', data);
        return;
      }
      
      // Build new index
      items.forEach(item => {
        if (item && item.item_name) {
          this.index.set(item.item_name, {
            tier: item.item_tier || 'Unknown',
            category: item.category || 'Unknown',
            subcategory: item.subcategory || 'Unknown'
          });
        }
      });
      
      this.lastUpdate = Date.now();
      console.log(`Search index updated with ${this.index.size} items`);
    } catch (error) {
      console.error('Failed to update search index:', error);
      // Keep existing index if update fails
    }
  }

  async ensureIndexFresh() {
    const now = Date.now();
    if (!this.lastUpdate || (now - this.lastUpdate) > this.updateInterval) {
      await this.updateIndex();
    }
  }

  search(query) {
    if (!query || query.length < 2) return [];
    
    const results = [];
    const lowerQuery = query.toLowerCase();
    
    for (const [itemName, details] of this.index) {
      if (itemName.toLowerCase().includes(lowerQuery)) {
        results.push({
          item_name: itemName,
          item_tier: details.tier,
          category: details.category,
          subcategory: details.subcategory
        });
      }
    }
    
    // Sort by relevance (exact matches first, then alphabetical)
    return results.sort((a, b) => {
      const aExact = a.item_name.toLowerCase().startsWith(lowerQuery);
      const bExact = b.item_name.toLowerCase().startsWith(lowerQuery);
      
      if (aExact && !bExact) return -1;
      if (!aExact && bExact) return 1;
      return a.item_name.localeCompare(b.item_name);
    }).slice(0, 10); // Limit to 10 suggestions
  }

  getItemDetails(itemName) {
    return this.index.get(itemName);
  }
}

export const searchIndex = new SearchIndex();