export const exportData = async (exportParams) => {
    try {
        const queryParams = new URLSearchParams();
        
        // Add export type
        queryParams.append('type', exportParams.type);
        
        // Add specific items if exporting specific items
        if (exportParams.type === 'specific' && exportParams.items) {
            exportParams.items.forEach(item => {
                queryParams.append('items[]', item);
            });
        }
        
        // Add filters
        if (exportParams.tiers && exportParams.tiers.length > 0) {
            exportParams.tiers.forEach(tier => {
                queryParams.append('tiers[]', tier);
            });
        }
        
        // Add category filters
        if (exportParams.categories && exportParams.categories.length > 0) {
            exportParams.categories.forEach(category => {
                queryParams.append('categories[]', category);
            });
        }
        
        // Add subcategory filters
        if (exportParams.subcategories && exportParams.subcategories.length > 0) {
            exportParams.subcategories.forEach(subcategory => {
                queryParams.append('subcategories[]', subcategory);
            });
        }
        
        if (exportParams.gearScoreMin) {
            queryParams.append('gearScoreMin', exportParams.gearScoreMin);
        }
        
        if (exportParams.gearScoreMax) {
            queryParams.append('gearScoreMax', exportParams.gearScoreMax);
        }
        
        if (exportParams.minPrice) {
            queryParams.append('minPrice', exportParams.minPrice);
        }
        
        if (exportParams.maxPrice) {
            queryParams.append('maxPrice', exportParams.maxPrice);
        }
        
        if (exportParams.dateFrom) {
            queryParams.append('dateFrom', exportParams.dateFrom);
        }
        
        if (exportParams.dateTo) {
            queryParams.append('dateTo', exportParams.dateTo);
        }
        
        const url = BASE ? `${BASE}/export?${queryParams.toString()}` : `/export?${queryParams.toString()}`;
        
        // Add debugging
        console.log('Export URL:', url);
        console.log('Export params:', exportParams);
        
        const response = await fetch(url, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json',
            },
        });
        
        if (!response.ok) {
            throw new Error(`Export failed: ${response.statusText}`);
        }
        
        return await response.json();
    } catch (error) {
        console.error('Export error:', error);
        throw error;
    }
};