import React, { useState, useEffect } from 'react';
import { exportData } from '../api/client';
import { searchIndex } from '../services/SearchIndex';
import '../styles/DataExport.css';

function DataExport() {
    const [exportType, setExportType] = useState('all');
    const [selectedItems, setSelectedItems] = useState([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [filters, setFilters] = useState({
        tiers: [],
        categories: [],
        subcategories: [],
        gearScoreMin: '',
        gearScoreMax: '',
        minPrice: '',
        maxPrice: '',
        dateFrom: '',
        dateTo: ''
    });
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState(null);
    const [suggestions, setSuggestions] = useState([]);
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [availableCategories, setAvailableCategories] = useState([]);
    const [availableSubcategories, setAvailableSubcategories] = useState([]);

    // Initialize search index and get available categories/subcategories on component mount
    useEffect(() => {
        const initializeData = async () => {
            await searchIndex.ensureIndexFresh();
            
            // Extract unique categories and subcategories from the search index
            const categories = new Set();
            const subcategories = new Set();
            
            for (const [itemName, details] of searchIndex.index) {
                if (details.category) categories.add(details.category);
                if (details.subcategory) subcategories.add(details.subcategory);
            }
            
            setAvailableCategories(Array.from(categories).sort());
            setAvailableSubcategories(Array.from(subcategories).sort());
        };
        
        initializeData();
    }, []);

    const exportTypes = [
        { value: 'all', label: 'All Listings' },
        { value: 'specific', label: 'Specific Items' }
    ];

    const tierOptions = [
        { value: 'I', label: 'Tier I' },
        { value: 'II', label: 'Tier II' },
        { value: 'III', label: 'Tier III' },
        { value: 'IV', label: 'Tier IV' },
        { value: 'V', label: 'Tier V' }
    ];

    const handleFilterChange = (field, value) => {
        setFilters(prev => ({
            ...prev,
            [field]: value
        }));
    };

    const handleTierChange = (tier) => {
        setFilters(prev => ({
            ...prev,
            tiers: prev.tiers.includes(tier)
                ? prev.tiers.filter(t => t !== tier)
                : [...prev.tiers, tier]
        }));
    };

    const handleCategoryChange = (event) => {
        const selectedCategory = event.target.value;
        setFilters(prev => ({
            ...prev,
            categories: selectedCategory ? [selectedCategory] : []
        }));
    };

    const handleSubcategoryChange = (event) => {
        const selectedSubcategory = event.target.value;
        setFilters(prev => ({
            ...prev,
            subcategories: selectedSubcategory ? [selectedSubcategory] : []
        }));
    };

    const handleItemSearch = async (value) => {
        setSearchTerm(value);
        if (value.length >= 2) {
            try {
                // Use the existing search index
                await searchIndex.ensureIndexFresh();
                const suggestions = searchIndex.search(value);
                setSuggestions(suggestions);
                setShowSuggestions(true);
            } catch (err) {
                console.error('Search error:', err);
                setSuggestions([]);
            }
        } else {
            setSuggestions([]);
            setShowSuggestions(false);
        }
    };

    const handleSuggestionClick = (item) => {
        if (!selectedItems.find(selected => selected.item_name === item.item_name)) {
            setSelectedItems(prev => [...prev, item]);
        }
        setSearchTerm('');
        setShowSuggestions(false);
    };

    const removeSelectedItem = (itemName) => {
        setSelectedItems(prev => prev.filter(item => item.item_name !== itemName));
    };

    const handleExport = async (format) => {
        setIsLoading(true);
        setError(null);
        
        try {
            const exportParams = {
                type: exportType,
                items: exportType === 'specific' ? selectedItems.map(item => item.item_name) : null,
                ...filters
            };

            const data = await exportData(exportParams);
            
            if (format === 'json') {
                downloadJSON(data, `listings_export_${new Date().toISOString().split('T')[0]}.json`);
            } else if (format === 'csv') {
                downloadCSV(data, `listings_export_${new Date().toISOString().split('T')[0]}.csv`);
            }
        } catch (err) {
            setError(err.message || 'Export failed');
        } finally {
            setIsLoading(false);
        }
    };

    const downloadJSON = (data, filename) => {
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    const downloadCSV = (data, filename) => {
        // Check if data exists and has the right structure
        if (!data || !data.data || !Array.isArray(data.data) || data.data.length === 0) {
            setError('No data to export to CSV');
            return;
        }

        // Extract the actual listings data from the response
        const listings = data.data;
        
        if (listings.length === 0) {
            setError('No listings found matching your criteria');
            return;
        }

        const headers = Object.keys(listings[0]);
        const csvContent = [
            headers.join(','),
            ...listings.map(row => 
                headers.map(header => {
                    const value = row[header];
                    if (value === null || value === undefined) {
                        return '';
                    }
                    if (typeof value === 'string' && (value.includes(',') || value.includes('"') || value.includes('\n'))) {
                        return `"${value.replace(/"/g, '""')}"`;
                    }
                    return value;
                }).join(',')
            )
        ].join('\n');

        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    return (
        <div className="data-export">
            <div className="export-header">
                <h2>Listings Export Tool</h2>
                <p>Export New World Trading Post listings in JSON or CSV format</p>
            </div>

            <div className="export-container">
                <div className="export-section">
                    <h3>Export Configuration</h3>
                    
                    <div className="form-group">
                        <label htmlFor="exportType">Export Type:</label>
                        <select
                            id="exportType"
                            value={exportType}
                            onChange={(e) => setExportType(e.target.value)}
                        >
                            {exportTypes.map(type => (
                                <option key={type.value} value={type.value}>
                                    {type.label}
                                </option>
                            ))}
                        </select>
                    </div>

                    {exportType === 'specific' && (
                        <div className="form-group">
                            <label>Select Items:</label>
                            <div className="item-search">
                                <input
                                    type="text"
                                    placeholder="Search for items..."
                                    value={searchTerm}
                                    onChange={(e) => handleItemSearch(e.target.value)}
                                />
                                {showSuggestions && suggestions.length > 0 && (
                                    <div className="suggestions">
                                        {suggestions.map(item => (
                                            <div
                                                key={item.item_name}
                                                className="suggestion-item"
                                                onClick={() => handleSuggestionClick(item)}
                                            >
                                                {item.item_name} (Tier {item.item_tier}, Category: {item.category})
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                            
                            {selectedItems.length > 0 && (
                                <div className="selected-items">
                                    <h4>Selected Items:</h4>
                                    {selectedItems.map(item => (
                                        <div key={item.item_name} className="selected-item">
                                            <span>{item.item_name} (Tier {item.item_tier})</span>
                                            <button
                                                onClick={() => removeSelectedItem(item.item_name)}
                                                className="remove-btn"
                                            >
                                                ×
                                            </button>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}

                    <div className="filters-section">
                        <h4>Filters</h4>
                        
                        <div className="form-group">
                            <label>Item Tiers:</label>
                            <div className="tier-checkboxes">
                                {tierOptions.map(tier => (
                                    <label key={tier.value} className="tier-checkbox">
                                        <input
                                            type="checkbox"
                                            checked={filters.tiers.includes(tier.value)}
                                            onChange={() => handleTierChange(tier.value)}
                                        />
                                        {tier.label}
                                    </label>
                                ))}
                            </div>
                        </div>

                        <div className="form-group">
                            <label htmlFor="categories">Category:</label>
                            <select
                                id="categories"
                                value={filters.categories[0] || ""}
                                onChange={handleCategoryChange}
                                className="filter-dropdown"
                            >
                                <option value="">All Categories</option>
                                {availableCategories.map(category => (
                                    <option key={category} value={category}>
                                        {category}
                                    </option>
                                ))}
                            </select>
                        </div>

                        <div className="form-group">
                            <label htmlFor="subcategories">Subcategory:</label>
                            <select
                                id="subcategories"
                                value={filters.subcategories[0] || ""}
                                onChange={handleSubcategoryChange}
                                className="filter-dropdown"
                            >
                                <option value="">All Subcategories</option>
                                {availableSubcategories.map(subcategory => (
                                    <option key={subcategory} value={subcategory}>
                                        {subcategory}
                                    </option>
                                ))}
                            </select>
                        </div>

                        <div className="gear-score-range">
                            <label>Gear Score Range:</label>
                            <div className="range-inputs">
                                <input
                                    type="number"
                                    placeholder="Min GS"
                                    value={filters.gearScoreMin}
                                    onChange={(e) => handleFilterChange('gearScoreMin', e.target.value)}
                                />
                                <span>to</span>
                                <input
                                    type="number"
                                    placeholder="Max GS"
                                    value={filters.gearScoreMax}
                                    onChange={(e) => handleFilterChange('gearScoreMax', e.target.value)}
                                />
                            </div>
                        </div>

                        <div className="price-range">
                            <label>Price Range:</label>
                            <div className="range-inputs">
                                <input
                                    type="number"
                                    placeholder="Min Price"
                                    value={filters.minPrice}
                                    onChange={(e) => handleFilterChange('minPrice', e.target.value)}
                                />
                                <span>to</span>
                                <input
                                    type="number"
                                    placeholder="Max Price"
                                    value={filters.maxPrice}
                                    onChange={(e) => handleFilterChange('maxPrice', e.target.value)}
                                />
                            </div>
                        </div>

                        <div className="date-range">
                            <label>Date Range:</label>
                            <div className="range-inputs">
                                <input
                                    type="date"
                                    value={filters.dateFrom}
                                    onChange={(e) => handleFilterChange('dateFrom', e.target.value)}
                                />
                                <span>to</span>
                                <input
                                    type="date"
                                    value={filters.dateTo}
                                    onChange={(e) => handleFilterChange('dateTo', e.target.value)}
                                />
                            </div>
                        </div>
                    </div>

                    <div className="export-actions">
                        <button
                            className="export-btn json-btn"
                            onClick={() => handleExport('json')}
                            disabled={isLoading || (exportType === 'specific' && selectedItems.length === 0)}
                        >
                            {isLoading ? 'Exporting...' : 'Export as JSON'}
                        </button>
                        
                        <button
                            className="export-btn csv-btn"
                            onClick={() => handleExport('csv')}
                            disabled={isLoading || (exportType === 'specific' && selectedItems.length === 0)}
                        >
                            {isLoading ? 'Exporting...' : 'Export as CSV'}
                        </button>
                    </div>

                    {error && (
                        <div className="error-message">
                            {error}
                        </div>
                    )}
                </div>

                <div className="export-info">
                    <h3>Export Information</h3>
                    <div className="info-grid">
                        <div className="info-item">
                            <h4>All Listings</h4>
                            <p>Export all current market listings with optional filtering by tier, gear score, price, and date range</p>
                        </div>
                        <div className="info-item">
                            <h4>Specific Items</h4>
                            <p>Export listings for specific items you select from the searchable item index</p>
                        </div>
                        <div className="info-item">
                            <h4>Filters</h4>
                            <p>Apply multiple filters to narrow down your export data. All filters are optional and can be combined.</p>
                        </div>
                        <div className="info-item">
                            <h4>Export Formats</h4>
                            <p>Download your data as JSON for development/analysis or CSV for spreadsheet applications</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

export default DataExport;
